head.script:
/*
 * 화면 동작
 * 1. 화면 로딩시 차트 데이터(chart_data.json)를 조회
 * 2. 상단 캔들스틱(chartTop) + 하단 거래량 막대(chartVol) 2단 차트를 렌더링
 * 3. 공시일 캔들 하단에 민트 다트형 화살표, 최고가(수치+▼)·최저가(▲+수치) 회색 마커 표시
 * 4. 마우스 이동시 두 차트의 crosshair 세로선을 동기화하고 상단 세로선 하단에 날짜 라벨 표시
 * 5. 커스텀 툴팁 표시 — 상단 OHLC·하단 날짜/거래량, TOOLTIP_TRIGGER 로 band/shape 선택
 * 6. 최하단 GridView(grd_discls)에 공시목록을 연동
 *
 * 구성
 * 1. 상단 캔들 차트(chartTop) + 하단 거래량 차트(chartVol)
 * 2. 공시목록 그리드(grd_discls · dlt_disclsList)
 *
 * 담긴 패턴
 * - 동적 서브미션 조회 ($c.sbm.executeDynamic)
 * - SBChart 렌더 ($c.ext.drawChartData) · 재조회 전 컨테이너 정리 (scwin.clearChart)
 * - 렌더 후 SVG 오버레이 — 공시 화살표·최고/최저가 마커 (getBBox·getCTM 좌표 변환)
 * - crosshair 커스텀 동기화 — 반대편 점선 미러 (getScreenCTM 역변환) + HTML 오버레이 날짜 라벨
 * - 커스텀 툴팁 (tooltip.custom) + 도형 hit-test 트리거 옵션 (TOOLTIP_TRIGGER)
 * - 리사이즈 대응 — 라이브러리의 svg 재생성 후 오버레이·hit-test·동기화 디바운스 재적용
 * - 진입점 try/catch 오류 처리 ($c.exception.handleError)
 *
 * 참고 문서
 * - 옵션·기능 정의 : sbchart/md/SBCHART_OPTIONS.md §4(tooltip.custom)·§9(crosshair)
 * - 문의 회신 : sbchart/md/SPCHART.md
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.CHART_DATA_URL = "/ui/sample/SBChart/CANDLESTICK/data/chart_data.json";

// ---- 차트 공통 상수 (SPCHART.md 회신 §1 반영) ----
scwin.CHART_Y_WIDTH    = 78;          // ★ 두 차트 공통 Y축 폭 — 플롯 영역 정렬 (SPCHART.md §3-2)
scwin.CHART_UP_COLOR   = "#E52528";   // 상승 : 빨강
scwin.CHART_DOWN_COLOR = "#1B64DA";   // 하락 : 파랑
scwin.NOTICE_COLOR     = "#2AC1BC";   // 공시일 마커 : 민트
scwin.HIGHLOW_COLOR    = "#637381";   // 최고/최저가 수치·삼각형 마커 색상 (회색)
scwin.TOOLTIP_TRIGGER  = "shape";      // ★ 툴팁 표시 방식 — "shape": 도형(캔들/막대) 위에서만(기본) | "band": 플롯 어디서나 해당 날짜 표시

scwin.DATES = [];                     // 인덱스→날짜(yyyymmdd) — x축이 인덱스라 tick/툴팁 환산용
scwin.ROWS  = [];                     // 조회 원본 행 — 커스텀 툴팁에서 거래량 등 참조
scwin.__tooltipHit = {};              // TOOLTIP_TRIGGER="shape" 용 hit-test 상태 (차트별 도형 bbox + 마지막 마우스 플롯 좌표)
scwin.__resizeTimer = null;           // 리사이즈 재적용 디바운스 타이머
scwin.__onResize = null;              // 리사이즈 핸들러 참조 — onpageunload 에서 제거용

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author WRM
 * @date 2026. 08. 26
 * @description 페이지로드 — 초기화(init) 후 차트 데이터 조회·렌더(selectChartData)
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    // 진입점 표준 오류 처리 — code-convention §오류 처리
    try {
        // 초기화 함수
        await scwin.init();

        // 차트 데이터 조회·렌더
        await scwin.selectChartData();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SPCHART_NOTICE.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author WRM
 * @date 2026. 08. 27
 * @description 초기화 — 차트 상태 초기화 + 리사이즈 대응 리스너 등록
 *   (차트 컨테이너 정리는 render 진입 시 clearChart 로 수행 — 재조회 경로에서도 항상 정리되도록)
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    // 차트 상태 초기화 (재진입 대비)
    scwin.ROWS  = [];
    scwin.DATES = [];

    // 리사이즈 대응 — 라이브러리가 리사이즈 시 svg 를 재생성해 커스텀 오버레이가 사라지고
    // hit-test 좌표 캐시가 구좌표로 남는다(헤드리스 실측). 재렌더는 라이브러리에 맡기고,
    // 라이브러리 재렌더가 끝난 뒤(디바운스) 오버레이·hit-test·동기화만 재적용한다.
    // (핸들러 참조를 보관 — onpageunload 에서 제거해 화면 이탈 후 고아 리스너를 남기지 않는다)
    scwin.__onResize = function () {
        clearTimeout(scwin.__resizeTimer);
        scwin.__resizeTimer = setTimeout(function () {
            if (!scwin.ROWS.length) { return; }
            scwin.drawNoticeArrows(chartTop, scwin.ROWS);        // 공시일 ▲ 재적용
            scwin.drawHighLowMarkers(chartTop, scwin.ROWS);      // 최고/최저가 마커 재적용
            scwin.syncCrosshair(chartTop, chartVol, scwin.ROWS); // 미러선·hit-test 재구축 (새 svg 기준)
            scwin.setupCrosshairXLabel(chartTop, chartVol);      // 날짜 라벨 재부착
        }, 250);
    };
    window.addEventListener("resize", scwin.__onResize);
};

/**
 * @method
 * @name scwin.onpageunload
 * @author WRM
 * @date 2026. 08. 27
 * @description 화면 이탈 — 차트 인스턴스 destroy($c.ext.destroyChart, 라이브러리 전역 resize
 *   리스너 해제)와 화면 resize 리스너 제거. 정리하지 않으면 화면 전환 후 브라우저 리사이즈 시
 *   라이브러리 resize 핸들러가 제거된 DOM 에 접근해 null.style 오류가 난다.
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageunload = function () {
    clearTimeout(scwin.__resizeTimer);
    if (scwin.__onResize) { window.removeEventListener("resize", scwin.__onResize); }
    $c.ext.destroyChart(chartTop);
    $c.ext.destroyChart(chartVol);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

// (해당 없음 — 차트 상호작용은 렌더 후 SVG/DOM 리스너로 등록 : syncCrosshair·setupShapeHit·setupCrosshairXLabel)


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectChartData
 * @author WRM
 * @date 2026. 08. 27
 * @description 차트 데이터 조회($c.sbm.executeDynamic) 및 후처리 — 공시목록 GridView 바인딩,
 *   차트 데이터 가공·2단 차트 렌더, crosshair 동기화·날짜 라벨 등 차트 상호작용 초기화
 * @param
 * @returns
 * @hidden N
*/
scwin.selectChartData = async function () {
    // 차트 데이터 조회
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const body = (res.responseJSON && res.responseJSON.body) ? res.responseJSON.body : {};

    // 공시목록 GridView 연동
    dlt_disclsList.setJSON(body.disclsList || []);

    // 차트 렌더 (공시일 마커는 chartList.gongsi + disclsList.trdDd 매칭으로 판정)
    const data = scwin.buildChartData(body.chartList, body.disclsList);
    scwin.ROWS  = data;
    scwin.DATES = data.map(function (r) { return r.date; });
    scwin.render(data);

    // 차트 상호작용 초기화
    scwin.syncCrosshair(chartTop, chartVol, data);   // 상/하 차트 crosshair 세로선 동기화
    scwin.setupCrosshairXLabel(chartTop, chartVol);  // 상단 세로선(네이티브/미러) 하단 날짜 라벨

    // 총 카운트 적용
    tbx_discls_cnt.setValue($c.num.formatNumber(dlt_disclsList.getRowCount()));
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.clearChart
 * @author WRM
 * @date 2026. 08. 26
 * @description 차트 컨테이너 정리. 재조회 렌더 전 호출 — 이전 차트 잔존 방지 (SPCHART.md §1-5).
 *   $c.ext.destroyChart 위임 — 인스턴스 destroy 로 라이브러리 전역 resize 리스너까지 해제
 *   (innerHTML 정리만으로는 리스너가 잔존해 리사이즈 시 null.style 오류)
 * @param {Object} comp 차트 컨테이너 그룹 컴포넌트
 * @returns
 * @hidden N
*/
scwin.clearChart = function (comp) {
    $c.ext.destroyChart(comp);
};

/**
 * @method
 * @name scwin.buildChartData
 * @author WRM
 * @date 2026. 08. 26
 * @description 차트 데이터 가공.
 *  - OHLC 가 모두 0 인 무효 행 제거(원천 데이터 결측 방어 — y domain 왜곡 방지)
 *  - 문자열 수치를 Number 로 변환
 *  - 공시일(gongsi true 또는 disclsList 의 trdDd 일치)은 isNotice 플래그만 부여
 *    ※ scatter combo(SPCHART.md §3-6 방법 B)는 라이브러리가 null 값을 객체로 오인(typeof 검사)해
 *      크래시하므로 사용하지 않는다 — 렌더 후 drawNoticeArrows(SVG 오버레이)로 ▲ 표시.
 * @param {Array} chartList 조회 원본 행 목록 (date·open·close·low·high·admnt·gongsi)
 * @param {Array} disclsList 공시목록 (trdDd 로 공시일 판정)
 * @returns {Array} 가공된 차트 데이터 행 목록
 * @hidden N
*/
scwin.buildChartData = function (chartList, disclsList) {
    const noticeDates = {};
    (disclsList || []).forEach(function (d) { noticeDates[d.trdDd] = true; });

    return (chartList || []).filter(function (r) {
        return !(Number(r.open) === 0 && Number(r.high) === 0 && Number(r.low) === 0);
    }).map(function (r) {
        return {
            date:  r.date,
            open:  Number(r.open),
            close: Number(r.close),
            low:   Number(r.low),
            high:  Number(r.high),
            admnt: Number(r.admnt),
            isNotice: (r.gongsi === true || r.gongsi === "true" || r.gongsi === "Y" || noticeDates[r.date] === true)
        };
    });
};

/**
 * @method
 * @name scwin.seriesShapes
 * @author WRM
 * @date 2026. 08. 26
 * @description 시리즈 도형 목록 추출 (헤드리스 DOM 실측 기반 — 클래스 셀렉터).
 *  - 캔들 차트 : 캔들 1개 = <g class="sbchart-bar sbchart-shape sbchart-shape-N"> (wick path + body rect)
 *  - 막대 차트 : <g class="sbchart-shapes ..."> 하위 rect (막대 1개 = rect 1개)
 * @param {Element} svg 차트 svg 요소
 * @param {Number} dataLen 데이터 행 수 (도형 수 일치 검증)
 * @returns {Array|null} 도형 목록 (미일치 시 null — 렌더 미완료)
 * @hidden N
*/
scwin.seriesShapes = function (svg, dataLen) {
    const candles = svg.querySelectorAll("g.sbchart-shape");
    const list = candles.length ? candles : svg.querySelectorAll("g.sbchart-shapes > rect");
    return (list.length === dataLen) ? Array.prototype.slice.call(list) : null;
};

/**
 * @method
 * @name scwin.drawNoticeArrows
 * @author WRM
 * @date 2026. 08. 26
 * @description 공시일 캔들 하단에 초록 ▲ 화살표를 그린다 (렌더 후 SVG 오버레이).
 *   각 캔들 도형의 getBBox 로 실제 좌표를 얻어 같은 좌표계(부모 그룹)에 path 를 추가한다.
 * @param {Object} comp 차트 컨테이너 그룹 컴포넌트
 * @param {Array} data 가공된 차트 데이터 (isNotice 플래그 참조)
 * @param {Number} tryCnt 재시도 횟수 (내부용 — 렌더 지연 방어, 최대 10회)
 * @returns
 * @hidden N
*/
scwin.drawNoticeArrows = function (comp, data, tryCnt) {
    const svg = document.querySelector("#" + comp.getID() + " svg");
    const candles = svg ? scwin.seriesShapes(svg, data.length) : null;
    if (!candles) {   // 렌더 지연 방어 — 최대 10회 재시도 (__drawSBChart 의 라이브러리 로드 지연 포함)
        if ((tryCnt || 0) < 10) { setTimeout(function () { scwin.drawNoticeArrows(comp, data, (tryCnt || 0) + 1); }, 100); }
        return;
    }
    svg.querySelectorAll("path.notice-arrow").forEach(function (el) { el.remove(); });   // 재적용(리사이즈) 대비 정리
    data.forEach(function (r, i) {
        if (!r.isNotice) { return; }
        const b = candles[i].getBBox();
        const cx = b.x + b.width / 2;
        const top = b.y + b.height + 6;   // 캔들(저가) 바로 아래
        const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
        // 꼭짓점 위 + 하단이 오목한 다트형 화살표 (아래 변을 Q 곡선으로 위로 파냄)
        p.setAttribute("d", "M " + cx + " " + top
                          + " L " + (cx + 6) + " " + (top + 11)
                          + " Q " + cx + " " + (top + 5) + " " + (cx - 6) + " " + (top + 11)
                          + " Z");
        p.setAttribute("class", "notice-arrow");
        p.setAttribute("fill", scwin.NOTICE_COLOR);
        p.setAttribute("pointer-events", "none");   // 차트 마우스 이벤트 방해 금지
        candles[i].parentNode.appendChild(p);   // 같은 그룹에 추가해 transform 승계
    });
};

/**
 * @method
 * @name scwin.drawHighLowMarkers
 * @author WRM
 * @date 2026. 08. 27
 * @description 최고가/최저가 마커 표시 (렌더 후 SVG 오버레이 — 참고 이미지 재현).
 *  - 최고가 캔들 위 : 수치 + 바로 아래 ▼(역삼각형)
 *  - 최저가 캔들 아래 : ▲(삼각형) + 바로 아래 수치
 *  - 색상은 HIGHLOW_COLOR(회색 #637381). 시리즈 그룹은 clip-path 로 잘릴 수 있어
 *    svg 루트에 추가한다(그룹 좌표 → getCTM 으로 루트 좌표 변환).
 * @param {Object} comp 차트 컨테이너 그룹 컴포넌트
 * @param {Array} data 가공된 차트 데이터 (high·low 참조)
 * @param {Number} tryCnt 재시도 횟수 (내부용 — 렌더 지연 방어, 최대 10회)
 * @returns
 * @hidden N
*/
scwin.drawHighLowMarkers = function (comp, data, tryCnt) {
    const svg = document.querySelector("#" + comp.getID() + " svg");
    const candles = svg ? scwin.seriesShapes(svg, data.length) : null;
    if (!candles) {   // 렌더 지연 방어 — 최대 10회 재시도
        if ((tryCnt || 0) < 10) { setTimeout(function () { scwin.drawHighLowMarkers(comp, data, (tryCnt || 0) + 1); }, 100); }
        return;
    }
    let hiIdx = 0, loIdx = 0;
    data.forEach(function (r, i) {
        if (r.high > data[hiIdx].high) { hiIdx = i; }
        if (r.low  < data[loIdx].low)  { loIdx = i; }
    });
    const oldLayer = svg.querySelector("g.notice-highlow");
    if (oldLayer) { oldLayer.remove(); }   // 재적용(리사이즈) 대비 정리
    const group = candles[0].parentNode;
    const toRoot = function (x, y) {   // 시리즈 그룹 좌표 → svg 루트 좌표
        const pt = svg.createSVGPoint();
        pt.x = x; pt.y = y;
        return pt.matrixTransform(group.getCTM());
    };
    const layer = document.createElementNS("http://www.w3.org/2000/svg", "g");
    layer.setAttribute("class", "notice-highlow");
    layer.setAttribute("pointer-events", "none");   // 차트 마우스 이벤트 방해 금지
    svg.appendChild(layer);

    const put = function (idx, value, isHigh) {
        const b = candles[idx].getBBox();
        const cx = b.x + b.width / 2;
        // 최저가 캔들이 공시일이면 민트 화살표(저가 +6~+17)와 겹치지 않게 아래로 내림
        const gap = (!isHigh && data[idx].isNotice) ? 13 : 0;
        const ay = isHigh ? b.y - 4 : b.y + b.height + 4 + gap;   // 삼각형 꼭짓점 y (캔들 쪽)
        const by = isHigh ? ay - 7 : ay + 7;                      // 삼각형 밑변 y
        const apex = toRoot(cx, ay), bl = toRoot(cx - 4, by), br = toRoot(cx + 4, by);
        const tri = document.createElementNS("http://www.w3.org/2000/svg", "path");
        tri.setAttribute("d", "M " + apex.x + " " + apex.y + " L " + bl.x + " " + bl.y + " L " + br.x + " " + br.y + " Z");
        tri.setAttribute("fill", scwin.HIGHLOW_COLOR);
        layer.appendChild(tri);
        const tp = toRoot(cx, isHigh ? by - 3 : by + 12);   // 수치 기준선 — 삼각형 밑변 위/아래
        const txt = document.createElementNS("http://www.w3.org/2000/svg", "text");
        txt.setAttribute("x", tp.x);
        txt.setAttribute("y", tp.y);
        txt.setAttribute("text-anchor", "middle");
        txt.setAttribute("fill", scwin.HIGHLOW_COLOR);
        txt.setAttribute("font-size", "11");
        txt.textContent = $c.num.formatNumber(value);
        layer.appendChild(txt);
    };
    put(hiIdx, data[hiIdx].high, true);    // 최고가 : 수치 + 바로 아래 ▼
    put(loIdx, data[loIdx].low,  false);   // 최저가 : ▲ + 바로 아래 수치
};

/**
 * @method
 * @name scwin.setupShapeHit
 * @author WRM
 * @date 2026. 08. 26
 * @description TOOLTIP_TRIGGER="shape" 용 hit-test 준비 — 도형 bbox 목록과 마지막 마우스 플롯 좌표를 __tooltipHit[key] 에 기록.
 *   capture 단계 등록 — 라이브러리 핸들러(툴팁 갱신)보다 먼저 좌표를 기록한다.
 * @param {String} key 차트 구분 키 ("top"|"vol")
 * @param {Element} svg 차트 svg 요소
 * @param {Array} shapes 시리즈 도형 목록 (seriesShapes 반환값)
 * @returns
 * @hidden N
*/
scwin.setupShapeHit = function (key, svg, shapes) {
    const group = shapes[0].parentNode;
    const MIN_HIT_H = 10;   // 최소 hit 높이 — 저거래량 막대(~1px)는 hover 판정이 불가능해 밑변 고정·위로 확장
    const st = scwin.__tooltipHit[key] = {
        boxes: shapes.map(function (s) {
            const b = s.getBBox();
            let y = b.y, h = b.height;
            if (h < MIN_HIT_H) { y = y + h - MIN_HIT_H; h = MIN_HIT_H; }   // 밑변(축) 고정, 위로 확장
            return { x: b.x, y: y, w: b.width, h: h };
        }),
        last: null
    };
    // capture 단계 등록 — 라이브러리 핸들러(툴팁 갱신)보다 먼저 좌표를 기록
    svg.addEventListener("mousemove", function (e) {
        const pt = svg.createSVGPoint();
        pt.x = e.clientX; pt.y = e.clientY;
        const loc = pt.matrixTransform(group.getScreenCTM().inverse());
        st.last = { x: loc.x, y: loc.y };
    }, true);
    svg.addEventListener("mouseleave", function () { st.last = null; }, true);
};

/**
 * @method
 * @name scwin.isOverShape
 * @author WRM
 * @date 2026. 08. 26
 * @description 마지막 마우스 플롯 좌표가 i번째 도형 bbox(±3px 허용 오차) 위인지 판정 — shape 트리거 툴팁용
 * @param {String} key 차트 구분 키 ("top"|"vol")
 * @param {Number} i 데이터 인덱스
 * @returns {Boolean} 도형 위 여부
 * @hidden N
*/
scwin.isOverShape = function (key, i) {
    const st = scwin.__tooltipHit[key];
    if (!st || !st.last || !st.boxes[i]) { return false; }
    const b = st.boxes[i], t = 3;   // 허용 오차(px)
    return st.last.x >= b.x - t && st.last.x <= b.x + b.w + t
        && st.last.y >= b.y - t && st.last.y <= b.y + b.h + t;
};

/**
 * @method
 * @name scwin.noticeTooltip
 * @author WRM
 * @date 2026. 08. 26
 * @description 상단 차트 커스텀 툴팁 — 날짜·시가·종가·고가·저가·거래량 (참고 이미지의 빨간 테두리 박스 형식).
 *   SBChart tooltip.custom 은 데이터 포인트(배열)를 받는다 — index 로 원본 행을 역참조한다.
 * @param {Array|Object} d 라이브러리가 전달하는 데이터 포인트
 * @returns {String} 툴팁 HTML (숨김 시 "" — :empty 규칙)
 * @hidden N
*/
scwin.noticeTooltip = function (d) {
    const p = (d && d.length) ? d[0] : d;
    const i = (p && p.index != null) ? p.index : ((p && p.x != null) ? p.x : -1);
    if (scwin.TOOLTIP_TRIGGER === "shape" && !scwin.isOverShape("top", i)) { return ""; }   // 도형 밖 — 숨김(:empty 규칙)
    const row = scwin.ROWS[i];
    if (!row) { return ""; }

    const fmt = function (v) { return $c.num.formatNumber(v); };
    return "<div style='background:#fff;border:1px solid #e74c3c;padding:6px 10px;font-size:12px;color:#c0392b;line-height:1.6;'>"
         + "날짜 : " + $c.date.formatDateTime(row.date, "yyyy-MM-dd") + "<br/>"
         + "시가 : " + fmt(row.open)  + "<br/>"
         + "종가 : " + fmt(row.close) + "<br/>"
         + "고가 : " + fmt(row.high)  + "<br/>"
         + "저가 : " + fmt(row.low)   + "<br/>"
         + "거래량 : " + fmt(row.admnt)
         + "</div>";
};

/**
 * @method
 * @name scwin.syncCrosshair
 * @author WRM
 * @date 2026. 08. 26
 * @description 상/하 차트 crosshair 세로선 동기화 (좌표 기반 미러링).
 *   마우스가 있는 차트에서 가장 가까운 캔들/막대의 중심 x 를 찾아, "반대편 차트"의
 *   같은 인덱스 위치에 세로선을 직접 그린다 — 라이브러리 내부 이벤트 구조에 의존하지 않아
 *   확실하게 동작한다(마우스가 있는 차트 자체는 네이티브 crosshair 가 표시).
 *   좌표는 시리즈 그룹(getScreenCTM 역변환) 기준이라 두 차트의 마진 차이와 무관.
 * @param {Object} compA 상단 차트 컨테이너 그룹 컴포넌트
 * @param {Object} compB 하단 차트 컨테이너 그룹 컴포넌트
 * @param {Array} data 가공된 차트 데이터
 * @param {Number} tryCnt 재시도 횟수 (내부용 — 렌더 지연 방어, 최대 10회)
 * @returns
 * @hidden N
*/
scwin.syncCrosshair = function (compA, compB, data, tryCnt) {
    const seriesInfo = function (comp) {
        const svg = document.querySelector("#" + comp.getID() + " svg");
        if (!svg) { return null; }
        const shapes = scwin.seriesShapes(svg, data.length);
        if (!shapes) { return null; }
        const centers = [];
        let bottom = 0;
        for (let si = 0; si < shapes.length; si++) {
            const b = shapes[si].getBBox();
            centers.push(b.x + b.width / 2);
            if (b.y + b.height > bottom) { bottom = b.y + b.height; }
        }
        return { svg: svg, group: shapes[0].parentNode, shapes: shapes, centers: centers, bottom: bottom };
    };
    const A = seriesInfo(compA);
    const B = seriesInfo(compB);
    if (!A || !B) {   // 렌더 지연 방어
        if ((tryCnt || 0) < 10) { setTimeout(function () { scwin.syncCrosshair(compA, compB, data, (tryCnt || 0) + 1); }, 100); }
        return;
    }
    // 플롯 바닥(x축 위치)을 시리즈 그룹 좌표로 환산 — 도형 최하단(info.bottom)은 캔들 차트에서
    // 최저가 위치까지만이라 세로선이 축까지 닿지 않는다. x축 실좌표 기준이 정확하다.
    const plotBottom = function (info) {
        const axis = info.svg.querySelector(".sbchart-axis-x");
        if (axis) {
            const ab = axis.getBoundingClientRect();
            const pt = info.svg.createSVGPoint();
            pt.x = ab.left; pt.y = ab.top;
            return pt.matrixTransform(info.group.getScreenCTM().inverse()).y;
        }
        return info.bottom;   // 축 미탐색 시 폴백
    };

    const makeLine = function (info) {
        const prev = info.svg.querySelector(".notice-mirror-line");
        if (prev) { prev.remove(); }   // 재적용(리사이즈) 대비 정리
        const ln = document.createElementNS("http://www.w3.org/2000/svg", "line");
        ln.setAttribute("class", "notice-mirror-line");   // 하단 hover 시 날짜 라벨 기준선으로도 사용
        ln.setAttribute("y1", 0);
        ln.setAttribute("y2", plotBottom(info));
        ln.setAttribute("stroke", "#C0C0C0");          // 네이티브 crosshair(.sbchart-crosshair-x)와 동일 스타일
        ln.setAttribute("stroke-dasharray", "3,3");    // 점선 3,3
        ln.setAttribute("stroke-width", "1");
        ln.setAttribute("visibility", "hidden");
        ln.setAttribute("pointer-events", "none");
        info.group.appendChild(ln);   // 시리즈 그룹에 추가해 transform 승계
        return ln;
    };
    const lineA = makeLine(A);   // 각 차트의 미러 세로선
    const lineB = makeLine(B);

    // shape 모드 hit-test 준비 + 빈 툴팁 잔상 제거(:empty — width/box-shadow 기본값 때문에 필요)
    scwin.setupShapeHit("top", A.svg, A.shapes);
    scwin.setupShapeHit("vol", B.svg, B.shapes);
    if (!document.getElementById("notice-tooltip-empty-fix")) {   // 재적용(리사이즈) 시 중복 방지
        const styleEl = document.createElement("style");
        styleEl.id = "notice-tooltip-empty-fix";
        styleEl.textContent = "#" + compA.getID() + " .sbchart-tooltip:empty, #" + compB.getID() + " .sbchart-tooltip:empty { display: none !important; }";
        document.head.appendChild(styleEl);
    }

    const mouseToPlotX = function (src, e) {
        // 마우스 clientX → 시리즈 그룹 좌표계 x (마진/transform 자동 반영)
        const pt = src.svg.createSVGPoint();
        pt.x = e.clientX; pt.y = e.clientY;
        return pt.matrixTransform(src.group.getScreenCTM().inverse()).x;
    };

    // 마우스가 있는 차트는 네이티브 crosshair+자기 툴팁, 반대편 차트에는 점선 미러(연속 추적)
    const wireMirror = function (src, dstLine) {
        const step = src.centers.length > 1 ? (src.centers[src.centers.length - 1] - src.centers[0]) / (src.centers.length - 1) : 0;
        const minX = src.centers[0] - step / 2;
        const maxX = src.centers[src.centers.length - 1] + step / 2;
        src.svg.addEventListener("mousemove", function (e) {
            const x = Math.max(minX, Math.min(maxX, mouseToPlotX(src, e)));
            dstLine.setAttribute("x1", x);
            dstLine.setAttribute("x2", x);
            dstLine.setAttribute("visibility", "visible");
        });
        src.svg.addEventListener("mouseleave", function () {
            dstLine.setAttribute("visibility", "hidden");
        });
    };
    wireMirror(A, lineB);   // 상단 hover → 하단에 점선
    wireMirror(B, lineA);   // 하단 hover → 상단에 점선
};

/**
 * @method
 * @name scwin.volumeTooltip
 * @author WRM
 * @date 2026. 08. 26
 * @description 하단 거래량 커스텀 툴팁 — 상단과 동일한 "라벨 : 값" 형식 (날짜/거래량), 네이티브 툴팁 색상(배경 rgba(0,0,0,.7)·글자 #fff)
 * @param {Array|Object} d 라이브러리가 전달하는 데이터 포인트
 * @returns {String} 툴팁 HTML (숨김 시 "" — :empty 규칙)
 * @hidden N
*/
scwin.volumeTooltip = function (d) {
    const p = (d && d.length) ? d[0] : d;
    const i = (p && p.index != null) ? p.index : ((p && p.x != null) ? p.x : -1);
    if (scwin.TOOLTIP_TRIGGER === "shape" && !scwin.isOverShape("vol", i)) { return ""; }   // 도형 밖 — 숨김(:empty 규칙)
    const row = scwin.ROWS[i];
    if (!row) { return ""; }
    // 네이티브 툴팁(.sbchart-tooltip) 색상 — 배경 rgba(0,0,0,.7)·글자 #fff
    return "<div style='background:rgba(0,0,0,.7);border-radius:5px;padding:6px 10px;font-size:12px;color:#fff;line-height:1.6;'>"
         + "날짜 : " + $c.date.formatDateTime(row.date, "yyyy-MM-dd") + "<br/>"
         + "거래량 : " + $c.num.formatNumber(row.admnt)
         + "</div>";
};

/**
 * @method
 * @name scwin.setupCrosshairXLabel
 * @author WRM
 * @date 2026. 08. 27
 * @description 상단 crosshair 세로선 하단에 x값(날짜) 라벨 표시.
 *   라이브러리는 이 구성에서 y값 라벨(.sbchart-crosshair-yvalue)만 그리므로,
 *   동일 스타일(배경 #C0C0C0·흰 글자 10px)의 라벨을 세로선(.sbchart-crosshair-x)의
 *   실제 위치에 맞춰 HTML 오버레이(절대배치 div)로 그린다. 하단 차트 hover 시에는 상단 미러선 기준.
 *   ※ svg 내부 추가 방식은 라이브러리의 svg 재구성과 충돌해 페인트가 차단됨(헤드리스 실측) — HTML 오버레이 사용.
 * @param {Object} comp 상단 차트 컨테이너 그룹 컴포넌트 (라벨 부착 대상)
 * @param {Object} compB 하단 차트 컨테이너 그룹 컴포넌트
 * @param {Number} tryCnt 재시도 횟수 (내부용 — 렌더 지연 방어, 최대 10회)
 * @returns
 * @hidden N
*/
scwin.setupCrosshairXLabel = function (comp, compB, tryCnt) {
    const box = document.getElementById(comp.getID());
    const svg = box ? box.querySelector("svg") : null;
    const volSvg = document.querySelector("#" + compB.getID() + " svg");
    if (!svg || !volSvg) {   // 렌더 지연 방어
        if ((tryCnt || 0) < 10) { setTimeout(function () { scwin.setupCrosshairXLabel(comp, compB, (tryCnt || 0) + 1); }, 100); }
        return;
    }
    if (getComputedStyle(box).position === "static") { box.style.position = "relative"; }   // 오버레이 기준 좌표

    const prevLbl = box.querySelector(".notice-crosshair-xvalue");
    if (prevLbl) { prevLbl.remove(); }   // 재적용(리사이즈) 대비 정리
    const lbl = document.createElement("div");
    lbl.className = "notice-crosshair-xvalue";
    lbl.style.cssText = "position:absolute;display:none;background:#C0C0C0;color:#fff;font-size:10px;"
        + "line-height:14px;height:14px;min-width:38px;text-align:center;border-radius:2px;"
        + "pointer-events:none;z-index:10;";
    box.appendChild(lbl);

    // 기준 세로선(네이티브 crosshair 또는 미러선)의 위치로 라벨 갱신 — 두 선 모두 동일 그룹 좌표계
    const updateFromLine = function (xline) {
        if (!xline) { return; }

        // 세로선의 화면 좌표(하단점) → 컨테이너 상대 좌표
        const lb = xline.getBoundingClientRect();
        const cb = box.getBoundingClientRect();
        const x = lb.left - cb.left;
        const bottom = lb.bottom - cb.top;

        // 세로선(그룹 좌표 x1)과 가장 가까운 캔들 인덱스 → 날짜 (x축 tick 과 동일한 MM-DD 표기)
        const lineX = parseFloat(xline.getAttribute("x1"));
        let best = 0, bd = Infinity;
        const boxes = (scwin.__tooltipHit.top && scwin.__tooltipHit.top.boxes) || [];
        for (let i = 0; i < boxes.length; i++) {
            const c = boxes[i].x + boxes[i].w / 2;
            const d = Math.abs(c - lineX);
            if (d < bd) { bd = d; best = i; }
        }
        const dt = scwin.DATES[best];
        lbl.textContent = dt ? dt.slice(4, 6) + "-" + dt.slice(6) : "";

        lbl.style.left = Math.round(x - 19) + "px";
        lbl.style.top = Math.round(bottom + 2) + "px";
        lbl.style.display = "block";
    };

    // 상단 hover — 네이티브 crosshair 세로선 기준
    svg.addEventListener("mousemove", function () {
        updateFromLine(svg.querySelector(".sbchart-crosshair-x"));
    }, true);
    svg.addEventListener("mouseleave", function () { lbl.style.display = "none"; }, true);

    // 하단 hover — 상단 미러 세로선 기준 (bubble 단계 등록: syncCrosshair 가 미러선 위치를
    // 갱신한 뒤 실행되도록 — 등록 순서상 wireMirror 리스너 다음)
    volSvg.addEventListener("mousemove", function () {
        const mirror = svg.querySelector(".notice-mirror-line");
        if (mirror && mirror.getAttribute("visibility") === "visible") { updateFromLine(mirror); }
    });
    volSvg.addEventListener("mouseleave", function () { lbl.style.display = "none"; });
};

/**
 * @method
 * @name scwin.render
 * @author WRM
 * @date 2026. 08. 26
 * @description 2단 차트 렌더 — 상단 캔들스틱($c.ext.drawChartData) + 공시/최고·최저가 오버레이, 하단 거래량 막대
 * @param {Array} data 가공된 차트 데이터 (buildChartData 반환값)
 * @returns
 * @hidden N
*/
scwin.render = function (data) {
    scwin.clearChart(chartTop);   // 재조회 대비 이전 차트 정리 — SPCHART.md §1-5
    scwin.clearChart(chartVol);

    // ── 상단: 캔들스틱 + 공시일 scatter 오버레이 ──
    $c.ext.drawChartData("candlestick", data, chartTop, {
        legend: { show: false },
        global: {
            crosshair: { show: true }          // 십자선 — X/Y 위치 표시 (SBCHART_OPTIONS.md §9)
        },
        tooltip: {
            custom: scwin.noticeTooltip        // 날짜·OHLC·거래량 커스텀 툴팁
        },
        axis: {
            y: { width: scwin.CHART_Y_WIDTH }, // 하단 차트와 플롯 정렬
            x: { tick: { format: function (v) {
                const d = scwin.DATES[v];
                return (d && v % 2 === 0) ? d.slice(4, 6) + "-" + d.slice(6) : "";   // MM-DD, 과밀 방지
            } } }
        },
        extend: {
            candlestick: {
                auto: true,
                inColor: scwin.CHART_UP_COLOR,     // 상승 빨강 (SPCHART.md §3-1)
                deColor: scwin.CHART_DOWN_COLOR,   // 하락 파랑
                marker: { show: false }            // 고점/저점 마커 대신 공시일 ▲ 오버레이 사용
            }
        },
        dataOpts: {
            keys: {
                x: "date",
                value: [ { open: "open", close: "close", low: "low", high: "high" } ]
            }
        }
    });
    scwin.drawNoticeArrows(chartTop, data);     // 공시일 ▲ 오버레이 (렌더 후)
    scwin.drawHighLowMarkers(chartTop, data);   // 최고/최저가 수치·삼각형 마커 (gray)

    // ── 하단: 거래량 막대 ──
    $c.ext.drawChartData("bar", data, chartVol, {
        legend: { show: false },
        global: { crosshair: { show: true } },
        tooltip: {
            custom: scwin.volumeTooltip   // "라벨 : 값" 형식 (날짜/거래량) — 상단과 통일
        },
        axis: {
            y: {
                width: scwin.CHART_Y_WIDTH,        // 상단 차트와 플롯 정렬
                tick: { format: function (v) { return $c.num.formatNumber(v); } }
            },
            x: { tick: { format: function () { return ""; } } }   // 날짜는 상단 차트에 표시
        },
        extend: { bar: { width: { ratio: 0.5 } } },
        dataOpts: { keys: { x: "date", value: [ "admnt" ] } }
    });
};
